OUT_PATH = Path("data/christian_core_terms.json")
BACKUP_PATH = DB_PATH.with_name("dictionary.before_christian_core_terms.sqlite3")
TAG = "キリスト教基礎追加"
SOURCE_NOTE = "聖書・キリスト教伝承・教義史をもとに辞典向けに整理"


def term(
    name: str,
    aliases: str,
    kind: str,
    domains: str,
    summary: str,
    note: str,
    see_also: str,
    *,
    mythology: str = "キリスト教/聖書",
    language: str = "Greek, Latin, Hebrew, Aramaic",
    tags: str = "",
) -> dict[str, str]:
    return {
        "term": name,
        "reading": "",
        "aliases": aliases,
        "language": language,
        "kind": kind,
        "mythology": mythology,
        "domains": domains,
        "tags": merge_multi_values("キリスト教, 聖書", tags, TAG),
        "summary": summary,
        "description": build_description(name, kind, domains, summary, note, see_also),
        "see_also": see_also,
        "sources": SOURCE_NOTE,
    }


def build_description(
    name: str,
    kind: str,
    domains: str,
    summary: str,
    note: str,
    see_also: str,
) -> str:
    return "\n\n".join(
        [
            summary,
            note,
            (
                f"辞書的には、{name}は「{kind}」として引ける項目であり、"
                f"関連する軸は「{domains}」。単語だけを見るより、聖書本文、教義、典礼、後世の伝承のどこで重要になるかを分けて読むと理解しやすい。"
            ),
            (
                "キリスト教周辺の語は、史実的人物、信仰上の称号、神学概念、象徴物、終末論の像が互いに重なりやすい。"
                "そのため、同じ名前でも「聖書中の役割」「教会での解釈」「美術や文学での使われ方」を分けておくと辞典として扱いやすくなる。"
            ),
            (
                f"関連語としては「{see_also}」を合わせて見るとよい。"
                "人物なら師弟関係や対立関係、出来事なら前後の物語、概念なら救済・罪・終末といった大きな流れの中で位置づけられる。"
            ),
            (
                "世界観設定に使う場合は、名称をそのまま借りるだけでなく、象徴、儀礼、禁忌、所属する共同体、対になる存在をメモしておくと、検索や逆引きがしやすい。"
                "特に天使・悪魔・聖遺物・終末論の語は、属性タグを付けておくと他神話の近い概念とも比較しやすい。"
            ),
        ]
    )


